// Package postgres owns the PostgreSQL connection: config, pool, transaction
// manager, migrations and the readiness probe. Queries are generated by
// sqld into gen/db from schema.sql + queries/*.sql (make db-gen); every
// repository is built over the ctx-aware executor so a query inside
// Tx.Do* joins the caller's transaction and auto-commits outside one.
package postgres

import (
	"context"
	"embed"
	"fmt"
	"net/url"
	"time"

	"github.com/exaring/otelpgx"
	"github.com/jackc/pgx/v5/multitracer"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/tracelog"

	"github.com/gopherex/pgtx"
	pgtxotel "github.com/gopherex/pgtx/contrib/otel"
	"github.com/gopherex/pgtx/pkg/tx"
	"github.com/gopherex/sqld/pkg/migrate"
	"github.com/gopherex/xlog"
	xlogpgx "github.com/gopherex/xlog/contrib/libs/pgx"
	"github.com/gopherex/xprobe"
)

// migrationsFS embeds the schema migrations (sqld format, applied under
// sqld's advisory lock).
//
//go:embed migrations/*.sql
var migrationsFS embed.FS

// Config is the `infra.postgres` section.
type Config struct {
	Host     string `json:"host" schemapb:"default=localhost;min_len=1"`
	Port     int    `json:"port" schemapb:"default=5432;gte=1;lte=65535"`
	User     string `json:"user" schemapb:"default=stroppy;min_len=1"`
	Password string `json:"password" schemapb:"default=stroppy;secret=true"`
	Database string `json:"database" schemapb:"default=stroppy;min_len=1"`
	//nolint:lll // struct tags
	SSLMode string `json:"sslmode" schemapb:"default=disable;in=[\"disable\",\"allow\",\"prefer\",\"require\",\"verify-ca\",\"verify-full\"]"`
	// QueryLogLevel bounds the per-query pgx log: "warn" keeps it quiet
	// (errors only), "info"/"trace" log every statement, "none" silences.
	//nolint:lll // struct tags
	QueryLogLevel string `json:"query_log_level" schemapb:"default=warn;in=[\"trace\",\"debug\",\"info\",\"warn\",\"error\",\"none\"]"`
	// Pool bounds; zero keeps the pgx default. Set explicitly in production:
	// the default MaxConns depends on the node's CPU count.
	PoolMaxConns          int32         `json:"pool_max_conns" schemapb:"default=0;gte=0"`
	PoolMinConns          int32         `json:"pool_min_conns" schemapb:"default=0;gte=0"`
	PoolMaxConnLifetime   time.Duration `json:"pool_max_conn_lifetime" schemapb:"default=0s"`
	PoolMaxConnIdleTime   time.Duration `json:"pool_max_conn_idle_time" schemapb:"default=0s"`
	PoolHealthCheckPeriod time.Duration `json:"pool_health_check_period" schemapb:"default=0s"`
}

// DSN renders a libpq URL.
func (c *Config) DSN() string {
	dsn := url.URL{
		Scheme: "postgres",
		User:   url.UserPassword(c.User, c.Password),
		Host:   fmt.Sprintf("%s:%d", c.Host, c.Port),
		Path:   c.Database,
	}
	q := dsn.Query()
	q.Set("sslmode", c.SSLMode)
	dsn.RawQuery = q.Encode()
	return dsn.String()
}

func (c *Config) applyPool(p *pgxpool.Config) {
	if c.PoolMaxConns > 0 {
		p.MaxConns = c.PoolMaxConns
	}
	if c.PoolMinConns > 0 {
		p.MinConns = c.PoolMinConns
	}
	if c.PoolMaxConnLifetime > 0 {
		p.MaxConnLifetime = c.PoolMaxConnLifetime
	}
	if c.PoolMaxConnIdleTime > 0 {
		p.MaxConnIdleTime = c.PoolMaxConnIdleTime
	}
	if c.PoolHealthCheckPeriod > 0 {
		p.HealthCheckPeriod = c.PoolHealthCheckPeriod
	}
}

// Client is the pool plus the transaction manager and the ctx-aware
// executor repositories are built over.
type Client struct {
	Pool *pgxpool.Pool
	Tx   tx.Trm
	TxDB tx.DB
}

// New opens the pool (OTel + xlog query tracers, pool gauges), builds the
// transaction manager and pings — fail fast on startup.
func New(ctx context.Context, cfg *Config, log *xlog.Logger) (*Client, error) {
	poolCfg, err := pgxpool.ParseConfig(cfg.DSN())
	if err != nil {
		return nil, fmt.Errorf("postgres: parse config: %w", err)
	}
	cfg.applyPool(poolCfg)

	logLevel, err := tracelog.LogLevelFromString(cfg.QueryLogLevel)
	if err != nil {
		return nil, fmt.Errorf("postgres: query log level %q: %w", cfg.QueryLogLevel, err)
	}
	logTracer, err := xlogpgx.NewTracer(log, xlogpgx.WithLogLevel(logLevel))
	if err != nil {
		return nil, fmt.Errorf("postgres: xlog tracer: %w", err)
	}
	poolCfg.ConnConfig.Tracer = multitracer.New(
		otelpgx.NewTracer(), logTracer)

	pool, err := pgxpool.NewWithConfig(ctx, poolCfg)
	if err != nil {
		return nil, fmt.Errorf("postgres: new pool: %w", err)
	}
	if err := pgtxotel.RegisterMetrics(pool); err != nil {
		log.Warn("postgres: pool metrics unavailable", xlog.ErrorCause(err))
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("postgres: ping %s:%d: %w", cfg.Host, cfg.Port, err)
	}
	txm, err := pgtx.NewTxManager(pool, tx.ReadCommitted())
	if err != nil {
		pool.Close()
		return nil, fmt.Errorf("postgres: tx manager: %w", err)
	}
	return &Client{Pool: pool, Tx: txm, TxDB: pgtx.NewTxDB(pool)}, nil
}

// Migrate applies the embedded migrations. Idempotent, advisory-locked.
func (c *Client) Migrate(ctx context.Context) error {
	if err := migrate.Migrate(ctx, c.Pool, migrationsFS); err != nil {
		return fmt.Errorf("postgres: migrate: %w", err)
	}
	return nil
}

// Probe reports pool reachability.
func (c *Client) Probe() xprobe.Probe {
	return xprobe.FromError(func(ctx context.Context) error { return c.Pool.Ping(ctx) })
}

// Close releases the pool.
func (c *Client) Close() { c.Pool.Close() }
